    trace_id = get_trace_id(request)
    with httpx.Client() as client:
        resp = client.get('http://localhost:3001/downstream', headers={'x-trace-id': trace_id})
        return {'traceId': trace_id, 'service': 'A', 'downstream': resp.json()}

# Downstream service B
app_b = FastAPI()

@app_b.get('/downstream')
def downstream(request: Request):
    return {'traceId': request.headers.get('x-trace-id'), 'service': 'B'}

def run_b():
    uvicorn.run(app_b, port=3001)

threading.Thread(target=run_b).start()

if __name__ == '__main__':
    uvicorn.run(app, port=port)

