package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"io"
	"net/http"
)

func getTraceID(r *http.Request) string {
	traceID := r.Header.Get("x-trace-id")
	if traceID != "" {
		return traceID
	}
	bytes := make([]byte, 16)
	rand.Read(bytes)
	return hex.EncodeToString(bytes)
}

func main() {
	go func() {
		http.HandleFunc("/downstream", func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(map[string]string{
				"traceId": r.Header.Get("x-trace-id"),
				"service": "B",
			})
		})
		http.ListenAndServe(":3001", nil)
	}()

	http.HandleFunc("/api", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		traceID := getTraceID(r)

		req, _ := http.NewRequest("GET", "http://localhost:3001/downstream", nil)
		req.Header.Set("x-trace-id", traceID)

		client := &http.Client{}
		resp, err := client.Do(req)
		if err != nil {
			w.WriteHeader(http.StatusInternalServerError)
			return
		}
		defer resp.Body.Close()
		body, _ := io.ReadAll(resp.Body)
		var downstreamData interface{}
		json.Unmarshal(body, &downstreamData)

		json.NewEncoder(w).Encode(map[string]interface{}{
			"traceId":    traceID,
			"service":    "A",
			"downstream": downstreamData,
		})
	})

	http.ListenAndServe(":3000", nil)
}

