import express, { Request, Response } from 'express';
import crypto from 'crypto';
const app = express();
const port = process.env.PORT || 3000;

app.use(express.json());

interface Span {
  spanId: string;
  service: string;
  duration?: number;
  parentSpan?: string | null;
  startTime?: number;
}

const traces: Record<string, Span[]> = {};

function startSpan(traceId: string, service: string, parentSpan?: string): Span {
  const spanId = crypto.randomUUID().split('-')[0];
  const span: Span = { spanId, service, parentSpan: parentSpan || null, startTime: Date.now() };
  if (!traces[traceId]) traces[traceId] = [];
  traces[traceId].push(span);
  return span;
}

function endSpan(traceId: string, spanId: string): void {
  const span = traces[traceId].find(s => s.spanId === spanId);
  if (span && span.startTime) {
    span.duration = Date.now() - span.startTime;
    delete span.startTime;
  }
}

app.get('/trace/:traceId', (req: Request, res: Response) => {
  const spans = (traces[req.params.traceId] || []).map(s => ({
    spanId: s.spanId,
    service: s.service,
    duration: s.duration || 0,
    parentSpan: s.parentSpan
  }));
  res.json({ traceId: req.params.traceId, spans });
});

app.listen(port, () => console.log(`Server on port ${port}`));

