from fastapi import FastAPI
import uuid
import time
import os

app = FastAPI()
port = int(os.getenv('PORT', 3000))

traces = {}

def start_span(trace_id, service, parent_span=None):
    span_id = str(uuid.uuid4()).split('-')[0]
    span = {
        'spanId': span_id,
        'service': service,
        'parentSpan': parent_span,
        'startTime': time.time()
    }
    if trace_id not in traces:
        traces[trace_id] = []
    traces[trace_id].append(span)
    return span

def end_span(trace_id, span_id):
    for s in traces.get(trace_id, []):
        if s['spanId'] == span_id and 'startTime' in s:
            s['duration'] = int((time.time() - s['startTime']) * 1000)
            del s['startTime']
            break

@app.get('/trace/{trace_id}')
def get_trace(trace_id: str):
    spans = []
    for s in traces.get(trace_id, []):
        spans.append({
            'spanId': s['spanId'],
            'service': s['service'],
            'duration': s.get('duration', 0),
            'parentSpan': s.get('parentSpan')
        })
    return {'traceId': trace_id, 'spans': spans}

