package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"
)

type Span struct {
	SpanID     string `json:"spanId"`
	Service    string `json:"service"`
	Duration   int64  `json:"duration"`
	ParentSpan string `json:"parentSpan,omitempty"`
}

type internalSpan struct {
	SpanID     string
	Service    string
	ParentSpan string
	StartTime  time.Time
	Duration   int64
}

var (
	traces = make(map[string][]*internalSpan)
	mu     sync.RWMutex
)

func generateSpanID() string {
	bytes := make([]byte, 8)
	rand.Read(bytes)
	return hex.EncodeToString(bytes)
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/trace/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		traceID := strings.TrimPrefix(r.URL.Path, "/trace/")
		mu.RLock()
		spans := make([]Span, 0)
		for _, s := range traces[traceID] {
			spans = append(spans, Span{
				SpanID:     s.SpanID,
				Service:    s.Service,
				Duration:   s.Duration,
				ParentSpan: s.ParentSpan,
			})
		}
		mu.RUnlock()
		json.NewEncoder(w).Encode(map[string]interface{}{"traceId": traceID, "spans": spans})
	})

	http.ListenAndServe(":"+port, nil)
}

